import { fireEvent, render } from '@testing-library/react';
import React from 'react';
import Error403 from './Error403';

describe('Error403 component', () => {
  it('Should render correctly with default params', () => {
    const buttonClickMock = jest.fn();

    const { getByText } = render(<Error403 onButtonClick={buttonClickMock} />);

    expect(getByText('Hmm... Access denied!')).toBeInTheDocument();
    expect(
      getByText("It looks like you don't have permission to access this page.")
    ).toBeInTheDocument();
  });

  it('Should render correctly with different text passed in props', () => {
    const buttonClickMock = jest.fn();

    const { getByText } = render(
      <Error403
        header="Testing header text"
        description="Testing description text"
        buttonText="Test button"
        onButtonClick={buttonClickMock}
      />
    );

    expect(getByText('Testing header text')).toBeInTheDocument();
    expect(getByText('Testing description text')).toBeInTheDocument();
    expect(getByText('Test button')).toBeInTheDocument();
  });

  it('Should call onButtonClick function when home button is clicked', () => {
    const buttonClickMock = jest.fn();

    const { getByText } = render(<Error403 onButtonClick={buttonClickMock} />);
    const button = getByText('Home');

    fireEvent.click(button);

    expect(buttonClickMock).toHaveBeenCalledTimes(1);
  });
});
